/**
 * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the two fiscal-year
 * digits of the {@link #getRegistrationDate() business-day-adjusted registration date}. The fiscal
 * year starts on 1 July and is named by the calendar year in which it ends, so a registration date
 * on or after 1 July belongs to the following calendar year's fiscal year (e.g. {@code 2026-07-01}
 * is {@code 'FY27'}) while an earlier date stays in the current one (e.g. {@code 2026-06-15} is
 * {@code 'FY26'}). This is the plain, user-facing fiscal year; it never carries the {@code 'V2'}
 * tag that the version-2 identifiers mix into their region. Returns {@code null} when no
 * registration date is available.
 *
 * @return the fiscal year, or {@code null} when it cannot be derived
 */
public String getFiscalYear() {
    if (this.registrationDate == null) {
        return null;
    }
    return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
}

/**
 * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July and
 * is named by the calendar year in which it ends: a date in July through December belongs to the
 * next calendar year's fiscal year, while January through June stays in the current one.
 *
 * @param date the date to classify
 * @return the fiscal year as a four-digit calendar year
 */
private static int fiscalYearOf(LocalDate date) {
    return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
}

/**
 * The single Luhn check digit (0-9) computed over the digits contained in the given value.
 * Non-digit characters (such as the letter region and hex characters) are ignored. This is the
 * {@code CHK} segment of the {@link #getMemberId() member id}, computed over the digits of its
 * {@code <REGION><FY><HASH8>} prefix.
 *
 * @param value the value whose digits the check digit is computed over
 * @return the Luhn check digit
 */
private static int luhnCheckDigit(String value) {
    int sum = 0;
    boolean dbl = true;
    for (int i = value.length() - 1; i >= 0; i--) {
        char c = value.charAt(i);
        if (c < '0' || c > '9') {
            continue;
        }
        int d = c - '0';
        if (dbl) {
            d *= 2;
            if (d > 9) {
                d -= 9;
            }
        }
        sum += d;
        dbl = !dbl;
    }
    return (10 - (sum % 10)) % 10;
}

/**
 * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
 * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
 * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
 * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
 * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
 * tenure, the tenure points are never awarded at create time.
 *
 * @return the membership points, a non-negative integer
 */
public Integer getMembershipPoints() {
    int points = 0;
    boolean hasEmail = this.email != null && !this.email.isBlank();
    if (hasEmail) {
        points += 2;
    }
    boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
    if (hasNoNamesakes) {
        points += 1;
    }
    if (this.householdSize != null && this.householdSize >= 3) {
        points += 2;
    }
    Long tenureFiscalYears = getTenureFiscalYears();
    if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
        points += 3;
    }
    return points;
}

