package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerIdentityDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName",
        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials", expression = "java(owner.getInitials())")
    @Mapping(target = "salutation", expression = "java(owner.getSalutation())")
    @Mapping(target = "apiVersion", expression = "java(2)")
    @Mapping(target = "identity", expression = "java(toOwnerIdentity(owner))")
    OwnerDto toOwnerDto(Owner owner);

    /**
     * Builds the nested version-2 identity object carried in the owner response, grouping the owner's
     * derived {@code memberId}, {@code identityKey} and {@code householdId}.
     *
     * @param owner the owner to read the identifiers from
     * @return the populated identity object
     */
    default OwnerIdentityDto toOwnerIdentity(Owner owner) {
        OwnerIdentityDto identity = new OwnerIdentityDto();
        identity.setMemberId(owner.getMemberId());
        identity.setIdentityKey(owner.getIdentityKey());
        identity.setHouseholdId(owner.getHouseholdId());
        return identity;
    }

    @Mapping(target = "memberId", ignore = true)
    @Mapping(target = "householdId", ignore = true)
    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

/**
 * Fixed region-to-timezone table used to derive {@link #getTimezone() timezone} from the owner's
 * {@link #getLocality() locality}: NSW->Australia/Sydney, VIC->Australia/Melbourne,
 * QLD->Australia/Brisbane. A locality not listed derives a {@code null} timezone.
 */
private static final Map<String, String> REGION_TIMEZONE = Map.of(
    "NSW", "Australia/Sydney",
    "VIC", "Australia/Melbourne",
    "QLD", "Australia/Brisbane");

/**
 * Email domains belonging to known disposable/throwaway mail providers. An exact match is rejected
 * at create time, so this table backs the looser {@link #isDisposableAdjacentEmail()} check that
 * flags an owner whose email domain is <em>adjacent</em> to one of these (a subdomain or a sibling
 * top-level domain that shares the provider's second-level name), feeding the {@link #getRiskFlag()
 * risk flag}.
 */
private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
    "mailinator.com",
    "tempmail.com",
    "guerrillamail.com");

/**
 * A link to this owner's own resource, {@code '/api/owners/'} followed by the owner's
 * {@link #getId() id}. Returns {@code null} before the owner has been assigned an id.
 *
 * @return the self link, or {@code null} when the owner has no id yet
 */
public String getSelfLink() {
    return this.getId() == null ? null : "/api/owners/" + this.getId();
